\bottomrule
\end{tabular}
\end{table}

\begin{table}[h]
\centering
\small
\caption{Cross-$\tau$ leave-one-out transfer (Pythia-1.4B). Train on three temperatures, test on the held-out one.}
\label{tab:multi_tau_cross}
\begin{tabular}{@{}lcc@{}}
\toprule
Holdout & Acc (\%) & d1v2 AUC \\
\midrule
$\tau{=}0.5$ & 52.2 & 0.176 \\
$\tau{=}0.7$ & 41.0 & 0.299 \\
$\tau{=}0.9$ & 46.4 & 0.277 \\
$\tau{=}1.1$ & 47.1 & 0.525 \\
\midrule
Mean & 46.7 & 0.319 \\
